"""Evidence-first author rubrics. No fact or conclusion is generated by an LLM here."""
from __future__ import annotations

import re
from collections.abc import Mapping
from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

from .article import clean_html
from .models import Article, FeedItem

FEATURE_RUBRICS = ("responsibility", "followup", "contrast", "cost", "reader")
FEATURE_LABELS = {
    "responsibility": "Кто отвечал", "followup": "Не забыли",
    "contrast": "Две России в один день", "cost": "Цена решения",
    "reader": "Разбор по запросу",
}


@dataclass(frozen=True)
class FeatureDraft:
    rubric: str
    body: str
    # Exact evidence is kept separate from computed/editorial text.
    evidence: tuple[str, ...] = ()
    extra_sources: tuple[tuple[str, str], ...] = ()


def sentences(text: str) -> list[str]:
    """Do not clip a sentence and accidentally remove attribution or negation."""
    marker = '\ue000'
    protected = re.sub(r'\b(тыс|млн|млрд|руб|г|им)\.(?=\s)', lambda match: match[1] + marker, text)
    return [part.strip().replace(marker, '.') for part in re.split(r"(?<=[.!?])\s+|\n+", protected)
            if 20 <= len(part.strip()) <= 300]


def build_responsibility(article: Article) -> FeatureDraft | None:
    rows = sentences(article.text)
    patterns = (
        ("Роли и решение по источнику", r"ответствен\w* за|заказчик|подрядчик|заключ\w* контракт|назнач\w* ответствен|решение принял"),
        ("Деньги по источнику", r"бюджет|стоимост|сумм\w* контракт|выдел\w*.*(?:рубл|млн|миллиард)"),
        ("Результат по источнику", r"не выполн|не заработ|сорван|срыв|задерж\w*|заверш\w*|не заверш|откры\w*|введ\w* в эксплуатац"),
    )
    selected: list[tuple[str, str]] = []
    for label, pattern in patterns:
        sentence = next((row for row in rows if re.search(pattern, row.lower())), None)
        if sentence and sentence not in [value for _, value in selected]:
            selected.append((label, sentence))
    if len(selected) < 2 or selected[0][0] != patterns[0][0]:
        return None
    body = clean_html(article.item.title) + "\n\n" + "\n\n".join(
        f"{label}: {value}" for label, value in selected
    )
    body += "\n\nРоль в проекте сама по себе не доказывает вину в нарушении."
    return FeatureDraft("responsibility", body, tuple(value for _, value in selected))


# Exact values and one shared currency/period are required. No estimated family size,
# average bill, salary, exchange rate or inflation rate is invented.
NUMBER = r"\d+(?:[ \u00a0\u202f]\d{3})*(?:[.,]\d+)?"
MONEY_CHANGE = re.compile(
    rf"\bс\s+(?P<before>{NUMBER})\s+до\s+(?P<after>{NUMBER})\s*"
    r"(?P<scale>тыс(?:яч\w*)?\.?|млн\.?|миллион\w*|млрд\.?|миллиард\w*)?\s*"
    r"(?P<unit>руб(?:лей|ля|ль|\.)?|₽)(?=\s|[.,;!?]|$)", re.I,
)
MINUTE_CHANGE = re.compile(rf"\bс\s+(?P<before>{NUMBER})\s+до\s+(?P<after>{NUMBER})\s+минут\w*", re.I)


def _number(value: str) -> Decimal:
    return Decimal(re.sub(r"\s", "", value).replace(",", "."))


def _display(value: Decimal) -> str:
    return format(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP), "f").rstrip("0").rstrip(".").replace(".", ",")


def build_cost(article: Article) -> FeatureDraft | None:
    for sentence in sentences(article.text):
        if re.search(r"предполож|возможно|может|планир|предваритель|не подтверж", sentence, re.I):
            continue  # A proposed or uncertain rate is not an actual new bill.
        money = MONEY_CHANGE.search(sentence)
        match = money or MINUTE_CHANGE.search(sentence)
        if not match:
            continue
        try:
            before, after = _number(match["before"]), _number(match["after"])
        except InvalidOperation:
            continue
        if before <= 0 or after <= 0 or before == after:
            continue
        scale = money["scale"] if money else None
        factor = Decimal("1")
        if scale:
            factor = Decimal("1000000000") if scale.lower().startswith(("млрд", "миллиард")) else (
                Decimal("1000000") if scale.lower().startswith(("млн", "миллион")) else Decimal("1000"))
        before, after = before * factor, after * factor
        if min(before, after) < Decimal('0.01') or max(before, after) > Decimal('1000000000000000000'):
            continue
        delta = after - before
        unit = "руб." if money else "мин."
        result = (f"Расчёт редакции: {_display(after)} − {_display(before)} = {_display(delta)} {unit}\n"
                  f"Относительное изменение: ({_display(after)} − {_display(before)}) / {_display(before)} × 100 = "
                  f"{_display(delta / before * 100)}%.")
        if money and re.search(r"(?:за|в) месяц|ежемесячн", sentence, re.I):
            result += (f"\nЕсли эта ежемесячная сумма сохранится 12 месяцев: {_display(delta)} × 12 = "
                       f"{_display(delta * 12)} руб. разницы за год. Это условный расчёт, не прогноз тарифов.")
        body = f"{clean_html(article.item.title)}\n\nПо источнику: {sentence}\n\n{result}"
        return FeatureDraft("cost", body, (sentence,))
    return None


def valid_cost_body(item: FeedItem, source_text: str, body: str) -> bool:
    """Editor approval must verify derived numbers by recomputing, not bypass validation."""
    marker = '\n\nПо источнику: '
    if marker not in body:
        return False
    title, rest = body.split(marker, 1)
    if title != clean_html(item.title) or '\n\nРасчёт редакции: ' not in rest:
        return False
    evidence = rest.split('\n\nРасчёт редакции: ', 1)[0]
    if evidence not in source_text:
        return False
    reconstructed = build_cost(Article(item, evidence))
    return bool(reconstructed and reconstructed.body == body)


SUBJECTS = (
    ("водоснабжение", r"водоснабж|водопровод|питьев\w* вод"),
    ("отопление", r"отоплен|теплоснабж|теплосет"),
    ("здравоохранение", r"больниц|поликлиник|медицинск\w* помощ"),
    ("дороги", r"дорожн|дорог\w*|мост\w*"),
    ("строительство", r"строител|стройк|жил\w* дом"),
    ("сервис", r"сервис|платформ|систем\w* оплат"),
    ("образование", r"школ|образован"),
)
COMMON = {"россия", "россии", "российские", "заявили", "сообщили", "правительство", "власти", "источник"}
COMMON |= {"министерство", "госдума", "россиян", "президент", "губернатор", 'сервис',
           'проект', 'больница', 'поликлиника', 'школа', 'мэр', 'чиновник', 'глава', 'совет'}


def _objects(text: str) -> set[str]:
    quoted = re.findall(r'(?:сервис\w*|платформ\w*|проект\w*|мост\w*|больниц\w*|поликлиник\w*|школ\w*)\s+«([^»]{2,60})»', text, re.I)
    numbered = re.findall(r'(?:больниц\w*|поликлиник\w*|школ\w*)\s*№\s*\d+', text, re.I)
    return {re.sub(r'\s+', ' ', value.lower().replace('ё', 'е')) for value in quoted + numbered}


def _anchors(text: str) -> set[str]:
    # Concrete proper names, not a fuzzy coincidence like two different criminal cases.
    names = re.findall(r"(?<![\w])(?:[А-ЯЁ][а-яё]{3,}|[А-ЯЁ]{3,})(?![\w])|«[^»]{3,60}»", text)
    return {name.lower().replace("ё", "е").strip("«»") for name in names if name.lower() not in COMMON}


def same_subject(left: str, right: str) -> bool:
    common_names = _anchors(left) & _anchors(right)
    subjects = {name for name, pattern in SUBJECTS if re.search(pattern, left, re.I)}
    other = {name for name, pattern in SUBJECTS if re.search(pattern, right, re.I)}
    # Require two named anchors (e.g. city + agency/service); never match just "Russia".
    common_objects = _objects(left) & _objects(right)
    places = lambda text: set(re.findall(r'(?:\b[Вв]|\b[Ии]з|\b[Дд]ля)\s+([А-ЯЁ][а-яё]{2,})', text))
    if places(left) and places(right) and not places(left) & places(right):
        return False
    return bool(common_objects) and bool(subjects & other) and len(common_names | common_objects) >= 2


def build_contrast(article: Article, history: list[Mapping[str, object]], now: datetime,
                   zone: object) -> FeatureDraft | None:
    reality = next((row for row in sentences(article.text)
                    if re.search(r"авари|не работает|не заработ|отключ|сорван|не хватает|закрыт|износ|не заверш", row, re.I)), None)
    if not reality:
        return None
    current_date = article.item.published_at
    if current_date is None or current_date.astimezone(zone).date() != now.astimezone(zone).date():
        return None
    for row in history:
        published = row["published_at"] if "published_at" in row.keys() else None
        if not published:
            continue
        old_date = datetime.fromisoformat(str(published))
        if old_date.astimezone(zone).date() != current_date.astimezone(zone).date():
            continue
        claim = next((part for part in sentences(str(row["content"] or ""))
                      if re.search(r"заяв\w*|сообщ\w*|по словам", part, re.I)
                      and re.search(r"готов|успеш|заверш|обеспеч|без перебо|полностью", part, re.I)
                      and not re.search(r'не\s+(?:готов|успеш|заверш|обеспеч)|\bнет\b|опроверг', part, re.I)), None)
        if not claim or not same_subject(claim, reality):
            continue
        if re.search(r'прошл\w* год|прежде|ранее|до этого|следующ\w* год|через год', claim + ' ' + reality, re.I):
            continue
        years = lambda value: set(re.findall(r"\b20\d{2}\b", value))
        if years(claim) != years(reality):
            continue
        months = lambda value: set(re.findall(r'\b(?:январ|феврал|март|апрел|ма[йяе]|июн|июл|август|сентябр|октябр|ноябр|декабр)\w*', value.lower()))
        if months(claim) != months(reality):
            continue
        body = (f"{clean_html(article.item.title)}\n\nЗаявление ({row['source']}): {claim}\n\n"
                f"Событие ({article.item.source}): {reality}\n\n"
                "Оба сообщения опубликованы в один день и относятся к одному объекту. "
                "Само сопоставление не устанавливает причину проблемы и не доказывает ложь автора заявления.")
        return FeatureDraft("contrast", body, (claim, reality),
                            ((str(row["source"]), str(row["canonical_url"] or row["url"])),))
    return None


def worth_following(title: str, topics: list[str]) -> bool:
    return bool(set(topics) & {"state_policy", "public_safety", "corruption", "human_rights", "repression"}
                and re.search(r"обещ|компенсац|выплат|расслед|ремонт|строит|отключ|авари|больниц|арест|приговор", title, re.I))


def followup_match(original_title: str, candidate: FeedItem) -> bool:
    if _anchors(original_title) & _anchors(candidate.title) and same_subject(original_title, candidate.title):
        return True
    # Repression stories: a person's FULL name or a quoted project/case name must match.
    people = set(re.findall(r"[А-ЯЁ][а-яё]+ [А-ЯЁ][а-яё]+", original_title))
    people = {name for name in people if not any(part.lower() in COMMON for part in name.split())}
    people = {name for name in people if not name.startswith(('Совет ', 'Госдума ', 'Минздрав ', 'Роспотребнадзор '))}
    return any(value.lower() in candidate.title.lower() for value in people)


def build_followup(watch: Mapping[str, object], current: Article | None,
                   now: datetime, channel: str) -> FeatureDraft:
    first = datetime.fromisoformat(str(watch["started_at"]))
    age = max(0, (now - first).days)
    body = f"История из выпуска {first:%d.%m.%Y}: {watch['title']}\n\nПрошло {age} дней.\n\n"
    sources = [(str(watch["source"]), str(watch["url"]))]
    if current:
        body += f"Новое сообщение ({current.item.source}): {clean_html(current.item.title)}"
        detail = next(iter(sentences(current.text)), None)
        if detail:
            body += "\n\nИз нового материала: " + detail
        sources.append((current.item.source, current.item.canonical_url or current.item.url))
    else:
        body += ("В доступных лентах, просмотренных в этом запуске, новых связанных сообщений за последние 48 часов "
                 "не нашли. Это не означает, что ничего не произошло, и не доказывает, что проблема не решена.")
    message_id = watch["telegram_message_id"]
    if channel.startswith("@") and message_id:
        sources.append(("Первый выпуск", f"https://t.me/{channel[1:]}/{message_id}"))
    return FeatureDraft("followup", body, (), tuple(sources))


def select_feature(article: Article, history: list[Mapping[str, object]], now: datetime,
                   zone: object, preferred: str = "auto") -> FeatureDraft | None:
    builders = {"responsibility": lambda: build_responsibility(article),
                "contrast": lambda: build_contrast(article, history, now, zone),
                "cost": lambda: build_cost(article)}
    if preferred in builders:
        return builders[preferred]()
    if preferred != "auto":
        return None
    # Rotate the preferred type by calendar date, but never force a rubric without evidence.
    order = list(builders)
    index = now.astimezone(zone).date().toordinal() % len(order)
    for name in order[index:] + order[:index]:
        draft = builders[name]()
        if draft:
            return draft
    return None
